        body: `▼ゼロから
飛行機の高度計は「気圧を高度に読み替える道具」です。でも気圧は天気や季節でその日ごとに変わるのに、どうやって統一的に高度を決めるのでしょうか？ 答えは「世界共通のモノサシ」を先に決めてしまうこと。それが国際標準大気（ISA：International Standard Atmosphere）です。ここでは代表的な高度と気圧・気温の対応をセットで覚え、実技でよく出る換算計算に強くなりましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 国際標準大気（ISA）とは
━━━━━━━━━━━━━━━━━━━━━━
・実際の大気は日々変動するため、比較や測器の基準として「仮想の平均的な大気」を定めたもの
・海面：気温15.0℃（288.15K）、気圧1013.25hPa、密度約1.225kg/m3
・対流圏（0〜11km）：気温は高度とともに一定の割合で低下（減率6.5℃/km）
・圏界面（高度11km）：気温−56.5℃で以降しばらく一定（成層圏下部は等温）

【図解】ISAの主要高度と気温・気圧の対応表
高度　　　気温　　　気圧（目安）
    0m　　15.0℃　　1013hPa
 1000m　　 8.5℃　　 899hPa
 2000m　　 2.0℃　　 795hPa
 5500m　 −20.8℃　　 約500hPa
11000m　 −56.5℃　　 約226hPa（圏界面）
→ 「1000mで約6.5℃・約110hPaずつ下がる」がおおまかな目安（ただし気圧は指数関数的なので下層ほど下がり幅が大きい）

━━━━━━━━━━━━━━━━━━━━━━
🔑 気圧高度・真高度・密度高度
━━━━━━━━━━━━━━━━━━━━━━
・気圧高度：観測した気圧をISAに当てはめて逆算した「見かけの高度」。高度計は気圧高度を表示する
・真高度：実際の海抜高度。気温が標準よりずれると気圧高度と真高度もずれる
・密度高度：空気の密度をISAに当てはめた高度。空気が薄いほど（高温・低圧・高標高ほど）密度高度は真高度より高くなる

【図解】気温が高い日の密度高度の伸び
標準的な日：標高0m空港 → 密度高度も約0m
猛暑日（気温が標準より+15℃）：
　空気が膨張して薄くなる → 見かけ上「高地にいる」のと同じ
　→ 密度高度は標高より数百m〜1000m以上高く出ることも
→ 高温の日は空気が薄く、航空機の揚力・エンジン出力が低下する一因

━━━━━━━━━━━━━━━━━━━━━━
🔑 実技計算ドリル：層厚と気温の関係
━━━━━━━━━━━━━━━━━━━━━━
【図解】層厚から平均気温を逆算する練習
問題：1000hPaと500hPaの間の層厚が5460mだった。この層の平均気温は標準的な層厚（約5500m）と比べて高い？低い？
　→ 層厚は平均気温に比例するので、5460m＜5500m ⇒ 平均気温は標準よりやや低い（寒気の層）
　→ 実技では層厚の広がり方（等層厚線の混み具合）から寒気・暖気の分布を読み取る

【図解】気圧高度の簡易換算ドリル
地上実況：気圧1000hPa（標準1013hPaよりわずかに低い）
　→ ISAでは1hPaの差はおよそ8m程度の高度差に相当する目安
　→ 1013−1000＝13hPa低い ⇒ 気圧高度はおよそ+100m前後高く出る計算
→ 「標準より気圧が低い＝その分だけ気圧高度は高く表示される」の向きを間違えない

⚠ ひっかけ注意
・ISAは「実在の大気」ではなく比較のための「基準」。毎日の実際の大気とは当然ずれる
・気圧高度と真高度は、気温が標準からずれるほど差が大きくなる（気温がISAより高いと気圧高度は真高度より低く出る）
・密度高度が高い＝空気が薄い、という意味。標高そのものが変わるわけではない
・圏界面（11km）から上は気温がしばらく一定（等温）で、対流圏のように下がり続けるわけではない

★ここだけ暗記
★ISA基準：海面15.0℃・1013.25hPa、対流圏減率6.5℃/km、圏界面11kmで−56.5℃
★気圧高度＝気圧をISAに当てはめた見かけの高度、真高度とは気温のずれ分だけ異なる
★密度高度＝空気の薄さをISAで高度換算したもの。高温・低圧ほど高く出る
★層厚は平均気温に比例。層厚が薄い＝その層は相対的に寒気`,
