・こうして電離した粒子が多く存在する層を電離層と呼ぶ。電離層は特定の周波数の電波を反射する性質を持つ
・電離層での電波の反射を利用することで、見通し距離を超えた遠方まで短波などの電波を届けることができる（既習の対流圏とは異なる、電波伝搬にとって重要な層）

【図解】電離層による電波の反射（模式）
地上の送信所
