        emoji: '🧪',
        body: `▼ゼロから
空気の「温度・気圧・密度」は三角関係で結ばれていて、2つが決まれば残りが決まります（状態方程式）。さらに、上下に動くたびに温度が変わってしまう空気塊に、引っ越しても変わらない「マイナンバー」を与えたのが温位です。空気の追跡調査に欠かせない道具を手に入れましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 気体の状態方程式
━━━━━━━━━━━━━━━━━━━━━━
p = ρ R T
・p：気圧(Pa)、ρ：密度(kg/m3)、T：気温(K)
・R：乾燥空気の気体定数 約287 J/(kg・K)

読み取れること：
○同じ気圧なら、気温が高い空気ほど密度が小さい（軽い）
○同じ気温なら、気圧が高いほど密度が大きい
→ 「暖かい空気は軽くて浮く」の物理的な根拠

【図解】状態方程式の三角関係
　　　気圧 p
　　　／　＼
　密度 ρ ─ 気温 T　　p = ρRT
→ 2つ決まれば残り1つが決まる
→ 湿った空気は水蒸気（分子量18＜乾燥空気約29）を含む分だけ
　同じ温度・気圧なら乾燥空気より軽い！

━━━━━━━━━━━━━━━━━━━━━━
🔑 温位：空気塊の「変わらない名札」
━━━━━━━━━━━━━━━━━━━━━━
温位（θ）＝その空気塊を乾燥断熱的に1000hPaまで移動させたときの温度（K）。

・空気塊が乾燥断熱変化（雲を作らない上下運動）をする限り、温位は一定に保存される
・高さの違う空気を「同じ土俵（1000hPa）」で比べられる
・温位が高い空気＝（同じ気圧に持ってくれば）暖かく軽い空気

【図解】温位の考え方
上空700hPa、気温3℃の空気塊を
乾燥断熱で1000hPaまで下ろしてみる（圧縮で昇温）
1000hPaに着いたときの温度が約29℃(302K)なら
→ この空気塊の温位は約302K
→ どの高度にいても「302Kの空気」として追跡できる

○安定な大気：温位が高さとともに増加
×温位が高さとともに減少している層：絶対不安定（すぐ対流が起こる）

━━━━━━━━━━━━━━━━━━━━━━
🔑 相当温位：水蒸気の分まで含めた名札
━━━━━━━━━━━━━━━━━━━━━━
相当温位（θe）＝空気塊に含まれる水蒸気をすべて凝結させ、潜熱を温度に変えたと考えて、1000hPaに下ろしたときの温位。

・乾燥断熱変化でも湿潤断熱変化（凝結を伴う変化）でも、ほぼ保存される
・「気温の高さ」と「水蒸気の多さ」の両方を1つの数値で表せる
・相当温位が高い空気＝暖かく湿った空気（雨のエネルギー源）

【図解】温位と相当温位の使い分け
　　　　　　保存される変化
・温位θ　　：乾燥断熱変化のみ
・相当温位θe：乾燥断熱変化＋湿潤断熱変化（凝結しても保存）
　例：
　同じ温位の空気A（乾燥）と空気B（多湿）
　→ 温位では区別できないが、相当温位はBの方が高い
→ 前線解析・大雨の解析では相当温位が主役

━━━━━━━━━━━━━━━━━━━━━━
🔑 実技での使いどころ
━━━━━━━━━━━━━━━━━━━━━━
・850hPa等相当温位線の混み合った帯（集中帯）＝前線帯の目安
・南から相当温位の高い空気（暖湿気）が流れ込む場所＝大雨の警戒サイン
・梅雨前線の解析では「850hPaで相当温位336K〜345K前後の等値線の集中帯」に注目することが多い

【図解】等相当温位線と前線帯
北　　318K ──────────
　　　324K ──────────
　　　330K ══════════╗集中帯
　　　336K ══════════╝＝前線帯
南　　345K ──────────
　　　　↑ 南側ほど高θe（暖かく湿った空気）
→ 等値線がぎゅっと混んだ場所が性質の違う空気の境目

⚠ ひっかけ注意
・温位の単位はK（ケルビン）。℃で答えない
・温位は湿潤断熱変化（凝結あり）では保存されない。凝結の潜熱で温位は上がる
・相当温位は凝結・蒸発があってもほぼ保存される（だから前線解析に使う）
・「湿った空気は乾いた空気より重い」は×。水蒸気は乾燥空気より分子量が小さく、湿った空気の方が軽い

★ここだけ暗記
★状態方程式 p=ρRT（乾燥空気の R≒287 J/(kg・K)）
★温位＝1000hPaに乾燥断熱で移したときの温度（K）。乾燥断熱変化で保存
★相当温位＝潜熱まで含めた温位。湿潤断熱変化でも保存
★850hPaの等相当温位線集中帯＝前線帯の解析の目安`,
