        body: `▼ゼロから
池に石を投げると波紋が広がるように、地球規模の大気にも「波」があります。中緯度の上空を吹く偏西風が南北に大きくうねる、あの蛇行（トラフとリッジの並び）こそがロスビー波（惑星波）です。回転する地球の上で、南北に動かされた空気が元に戻ろうとする性質が波を生み出します。

━━━━━━━━━━━━━━━━━━━━━━
🔑 ロスビー波が生まれる理由
━━━━━━━━━━━━━━━━━━━━━━
・地球渦度（コリオリパラメータf）は緯度で変わり、高緯度ほど大きい
・空気の柱が南北に押し出されると、地球渦度の変化を打ち消すように相対渦度が変わり、もとの緯度へ戻ろうとする復元力がはたらく
・この復元力が「波」として東西に伝わる（ただし波自体は西向きに伝わる性質を持つ）

【図解】ロスビー波の復元力のイメージ
北へ押し出された空気塊
　→ 地球渦度（大）に対応するよう相対渦度が変化（時計回りの回転が強まる）
　→ 南向きの動きが生まれ、元の緯度へ戻ろうとする
　→ 行き過ぎてまた戻る…の繰り返しが南北の蛇行＝波になる
→ 「地球が丸い（渦度が緯度で違う）」ことが波の起源

━━━━━━━━━━━━━━━━━━━━━━
🔑 波の数と伝わる速さ
━━━━━━━━━━━━━━━━━━━━━━
・地球を一周する波の数（波数）が少ない波ほど「超長波」と呼ばれ、動きが遅い（ほとんど停滞することも）
・波数が多い波ほど「短波」で、偏西風に流されて速く東進する
・超長波（波数1〜3程度）は大陸配置や大規模な海陸分布に対応して形作られ、季節平均的な位置はあまり変わらない
・短波は500hPa天気図で日々見られるトラフ・リッジの動きに対応し、天気の日々変化を作る

【図解】超長波と短波の役割分担
超長波（波数少・動き遅い）：季節を通じた気圧配置の骨格（大陸の寒気の巣、海洋高気圧の位置）
　　＋
短波（波数多・動き速い）：その骨格に乗って移動する日々のトラフ・リッジ
　　＝
実際の天気図：骨格＋日々の変化が重なって見える
→ 「大きくゆっくりの波」の上に「小さく速い波」が乗っているイメージ

━━━━━━━━━━━━━━━━━━━━━━
🔑 ブロッキング：波が「詰まる」現象
━━━━━━━━━━━━━━━━━━━━━━
・偏西風の蛇行が非常に大きくなると、高緯度側に切り離された高気圧（ブロッキング高気圧）ができ、通常の西風の流れが「せき止め」られる
・ブロッキングが起きると、その付近の天気パターン（猛暑・寒波・長雨など）が数日〜数週間にわたって停滞しやすい
・日本付近では、オホーツク海高気圧が梅雨期に停滞するのもブロッキング的な現象の一例とされる

【図解】平常時とブロッキング時の流れの違い
平常時：─────╲╱─────╲╱───── （波が西から東へどんどん通過）
ブロッキング時：──╲　　╱── （高気圧が高緯度に切り離されて居座る）
　　　　　　　　　╲＿＿╱
　　　　　　　　　流れが分流・停滞
→ 「同じ天気が長引く」のはブロッキングのサイン

⚠ ひっかけ注意
・ロスビー波（の位相）は西向きに伝わる性質を持つが、偏西風に流されるため実際の見かけの動きは東進することが多い
・波数が少ない波（超長波）ほど動きが遅い。「波数が多いほど遅い」は×
・ブロッキング高気圧は移動性高気圧とは別物。移動性高気圧は次々に東進するが、ブロッキングは同じ場所に長く居座る
・ロスビー波の復元力の源は地球渦度（コリオリパラメータ）が緯度で変わることであり、単なる気圧差ではない

★ここだけ暗記
★ロスビー波＝地球渦度の緯度変化による復元力が生む惑星規模の波。西向きに伝わる性質を持つ
★超長波（波数少）は動き遅く季節の骨格を作り、短波（波数多）は速く動き日々の天気を作る
★ブロッキング高気圧＝偏西風の流れをせき止め、同じ天気パターンを長引かせる
★梅雨期のオホーツク海高気圧の停滞もブロッキング的現象の一例`,
