        id: 'kansoku-05',
        title: '観測誤差と品質管理',
        emoji: '🔍',
        body: `▼ゼロから
どんなに優れた測器でも、観測にはわずかな誤差がつきものです。大切なのは「誤差ゼロを目指す」ことよりも、「誤差の性質を理解し、おかしなデータを見抜く」ことです。膨大な観測データが天気図や数値予報に使われる前に、どのようにふるいにかけられているかを見ていきましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 誤差の種類
━━━━━━━━━━━━━━━━━━━━━━
・機器誤差：測器そのものの精度の限界や、故障・劣化によって生じる誤差
・代表性誤差：観測地点の値が、その周辺の広い範囲を代表しきれないことによる誤差（例：ビルの谷間の風速計は周辺の風を代表しにくい）
・観測手法の誤差：観測の手順や設置環境（日射の当たり方、周囲の建物など）に起因する誤差
→ 誤差は「測器の問題」だけでなく「その場所ならではの事情」からも生まれる

【図解】代表性誤差のイメージ
広い平野の観測点　　　：周辺の広い範囲の状態をよく代表する
都市のビル街の観測点　：局所的な風の乱れ・日射の遮蔽の影響を受けやすく、周辺を代表しにくいことがある
→ 同じ精度の測器を使っていても、置かれた場所によって「その値がどこまで広い範囲を代表するか」は変わる

━━━━━━━━━━━━━━━━━━━━━━
🔑 品質管理（QC）の考え方
━━━━━━━━━━━━━━━━━━━━━━
・品質管理：観測されたデータが、明らかに物理的にありえない値や、周囲の観測・過去の傾向と大きく矛盾する値でないかをチェックし、異常なデータを取り除く、または重みを下げる処理
・チェックの視点の例：観測可能な範囲を超えていないか（物理的な限界値のチェック）、周辺の観測点と比べて極端に違わないか（空間的な整合性のチェック）、直前の観測値から急激に飛躍していないか（時間的な整合性のチェック）
・数値予報のデータ同化（既習）でも、品質管理を通過したデータだけが、観測と前回予報を混ぜ合わせる計算に使われる

【図解】品質管理のチェックの流れ
観測データが届く
　↓
① 物理的にありえない値でないか（範囲チェック）
　↓
② 周辺の観測点と比べて極端に違わないか（空間チェック）
　↓
③ 直前の値から急激に飛躍していないか（時間チェック）
　↓
問題なければ採用、疑わしければ除外・重み低下 → データ同化・天気図の作成へ
→ 「疑わしきは除外」の姿勢が、信頼できる観測網を支える

━━━━━━━━━━━━━━━━━━━━━━
🔑 均質化：長期間のデータをそろえる工夫
━━━━━━━━━━━━━━━━━━━━━━
・長期間の気候の変化を調べる際、観測地点の移転や、測器の更新、周辺の環境の変化（都市化など）によって、単純に過去と現在のデータを比べると、気候そのものの変化以外の要因が混ざってしまうことがある
・こうした観測条件の変化による見かけ上のずれを補正し、長期間にわたって比較可能なデータに整えることを均質化と呼ぶ
・気候変動の長期的な傾向（既習）を議論する際には、この均質化がなされたデータが土台として重要になる

⚠ ひっかけ注意
・観測誤差は測器の精度だけの問題ではなく、観測地点の環境（代表性）にも大きく左右される
・品質管理は「誤差を完全にゼロにする」ものではなく、「明らかに異常な値を検出・除外する」ための処理である
・都市化などによる周辺環境の変化は、気候変動そのものとは別に、観測データに見かけ上の変化をもたらしうる（均質化で補正が必要な理由）
・数値予報の初期値は「観測値そのもの」ではなく、品質管理とデータ同化を経た「解析値」である（既習の再確認）

★ここだけ暗記
★観測誤差＝機器誤差＋代表性誤差＋観測手法の誤差など、複数の要因からなる
★品質管理（QC）＝範囲・空間・時間の整合性から異常なデータを検出・除外する処理
★均質化＝観測環境の変化による見かけ上のずれを補正し、長期比較を可能にする処理
★数値予報の初期値は品質管理・データ同化を経た「解析値」であり観測値そのものではない`,
