        body: `▼ゼロから
前線とは「性質の違う空気のかたまり（気団）がぶつかる境目」です。お風呂に熱いお湯を足すと、熱い層と冷たい層の間にゆらゆらした境目ができますよね。大気でも、冷たく重い空気と暖かく軽い空気は簡単には混ざらず、境目の面（前線面）ができます。その面が地面と交わる線が、天気図の「前線」です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 天気図の基本要素
━━━━━━━━━━━━━━━━━━━━━━
① 等圧線：気圧の等しい地点を結ぶ。4hPaごとに実線、20hPaごとに太線
② 高気圧（H）：まわりより気圧が高い。下降気流で天気は良い傾向
③ 低気圧（L）：まわりより気圧が低い。上昇気流で天気は悪い傾向
④ 前線：気団の境目。天気の急変ポイント
⑤ 気圧の谷・尾根：等圧線がV字（谷）や逆V字（尾根）にたわむ場所

━━━━━━━━━━━━━━━━━━━━━━
🔑 前線の4種類
━━━━━━━━━━━━━━━━━━━━━━
・温暖前線（記号：半円）…暖気が寒気の上にゆっくり這い上がる
・寒冷前線（記号：三角）…寒気が暖気の下に潜り込み突き上げる
・停滞前線（半円と三角が互い違い・逆向き）…押し合いが互角でほぼ動かない（梅雨前線・秋雨前線）
・閉塞前線（半円と三角が同じ側）…寒冷前線が温暖前線に追いついた状態

【図解】温暖前線の鉛直断面（進行方向：右）
・前線面の傾きはゆるやか（約1/100〜1/300）
・上空ほど雲が高く、進行方向側から巻雲→巻層雲→高層雲→乱層雲の順に並ぶ
・前線面の上側：暖気（軽い）、下側：寒気（重い）
・乱層雲の下では、しとしと雨が広い範囲に降る
→ 雲の順番：巻雲→巻層雲→高層雲→乱層雲（だんだん低く厚く）
→ 通過後：気温上昇、風向は南寄りに変化（北半球では時計回りに変化）

【図解】寒冷前線の鉛直断面（進行方向：右）
・前線面は急な傾き（約1/25〜1/100）
・寒気（重い）が暖気（軽い）の下に潜り込み、暖気を押し上げる
・押し上げられた暖気の中に積乱雲⚡が発達する
→ 狭い範囲にザッと強い雨・雷・突風・ひょうも
→ 通過後：気温急降下、風向は南寄り→北寄りへ急変、気圧は上昇

【図解】温暖前線と寒冷前線の比較表
項目　　　　温暖前線　　　寒冷前線
前線面の傾き　ゆるやか　　　急
雲　　　　　層状（乱層雲）　対流性（積乱雲）
雨の範囲　　広い　　　　　狭い
雨の強さ　　弱く長い　　　強く短い
通過後の気温　上がる　　　　下がる
→ 「ゆっくり広く」対「激しく狭く」の対比で覚える

━━━━━━━━━━━━━━━━━━━━━━
🔑 等圧線と風の読み方
━━━━━━━━━━━━━━━━━━━━━━
・等圧線の間隔が狭い → 気圧傾度力が大きい → 風が強い
・北半球の地上風は、低気圧へ反時計回りに吹き込み、高気圧から時計回りに吹き出す
・等圧線がキンク（折れ曲がり）している場所は前線やシアーラインを疑う

⚠ ひっかけ注意
・前線記号の飾り（三角・半円）は前線の進行方向側に付く。停滞前線は両側に互い違い
・温暖前線の雨は前線の「前方（進行方向側）」の広い範囲、寒冷前線の雨は前線付近〜「後方」の狭い範囲
・寒冷前線通過の3点セット「気温急降下・風向急変（南寄り→北寄り）・気圧上昇」は実技頻出
・「停滞前線＝弱い雨」とは限らない。梅雨末期の停滞前線は大雨の常連

★ここだけ暗記
★等圧線：4hPaごと実線・20hPaごと太線
★温暖前線：傾きゆるやか・層状の雲・広く長い雨・通過後は気温上昇
★寒冷前線：傾き急・積乱雲・狭く強い雨・通過後は気温低下と風向急変
★停滞前線＝梅雨前線・秋雨前線、閉塞前線＝寒冷が温暖に追いついた形`,
