        body: `▼ゼロから
「降水確率30%」で雨が降ったら予報は外れでしょうか？ 実は外れではありません。30%とは「同じ予報を100回出したら、およそ30回は1mm以上の雨が降る」という意味。天気予報は「当たる・外れる」の二択ではなく、「どのくらい起こりやすいか」を数字で伝える確率の情報なのです。

━━━━━━━━━━━━━━━━━━━━━━
🔑 降水確率の正しい意味
━━━━━━━━━━━━━━━━━━━━━━
・「予報区内で、対象時間内に、1mm以上の降水がある確率」
・10%刻みで発表（四捨五入）
・雨の「強さ」や「量」や「降る時間の長さ」の情報は含まない！

【図解】降水確率70%の意味
同じ気象条件が100回あったら…
☔☔☔☔☔☔☔（約70回は1mm以上の雨）
☀☀☀（約30回は降らない）
→ 70%でも降らない日はある。それは「外れ」ではなく確率どおり
→ 確率10%でも10回に1回は降る

【図解】降水確率にまつわる誤解の整理
×確率が高い＝雨が強い　　　→ 強さとは無関係
×確率50%＝半日雨　　　　　→ 時間の長さとも無関係
×確率0%＝絶対降らない　　　→ 0%は「5%未満」の意味（四捨五入）
○確率＝1mm以上の雨の降りやすさ
→ 「起こりやすさ」だけを表す数字と割り切る

━━━━━━━━━━━━━━━━━━━━━━
🔑 カオス：予報に限界がある理由
━━━━━━━━━━━━━━━━━━━━━━
大気には「初期値のごくわずかな違いが、時間とともに指数関数的に拡大する」というカオスの性質があります（バタフライ効果）。

・観測には必ず誤差がある → 初期値も完全ではない
・その誤差が計算を進めるほど成長する
・決定論的な予報の実用的な限界は理論上2週間程度とされる

【図解】カオスによる予報の分岐
初期値のズレ（ごく小さい）が時間とともに拡大する
・1日後：ほぼ同じ未来
・3日後：少し違う未来
・7日後：かなり違う未来
・2週間後：全く違う未来もあり得る
→ 予報期間が延びるほど「幅」を持った情報（確率・信頼度）で伝えるのが科学的に誠実

━━━━━━━━━━━━━━━━━━━━━━
🔑 アンサンブル予報：不確かさを測る技術
━━━━━━━━━━━━━━━━━━━━━━
・初期値にわざと小さなばらつきを与えて多数の予報（メンバー）を計算
・メンバー間のばらつき（スプレッド）が小さい → 信頼度が高い
・ばらつきが大きい → どの未来もあり得る＝信頼度が低い
・週間予報・台風進路予報・季節予報（1か月予報など）で活用

【図解】良い確率予報の条件（信頼度曲線の考え方）
「30%」と言った日を全部集める → 実際に約30%の日で雨ならOK
「70%」と言った日を全部集める → 実際に約70%の日で雨ならOK
予報確率と実際の頻度がそろっている ＝ 信頼度の高い確率予報
×いつも50%ばかり言う予報 → 情報量が少ない（メリハリがない）
○0%や100%に近い予報を高精度で出せる → 情報価値が高い
→ 確率予報は「当たり外れ」でなく「確率と頻度の一致＋メリハリ」で評価

⚠ ひっかけ注意
・降水確率は「1mm以上」が基準。0.5mmの霧雨では「降水なし」扱い
・降水確率と雨の強さ・量は無関係（頻出のひっかけ！）
・「観測を完璧にすれば無限に先まで予報できる」は×。カオスのため原理的な限界がある
・アンサンブルのスプレッドが大きい＝悪い予報ではなく「不確かさが大きいという情報」

★ここだけ暗記
★降水確率＝1mm以上の降水がある確率（強さ・量・時間とは無関係）
★カオス＝初期値の微小誤差が拡大 → 決定論的予報の限界は約2週間
★アンサンブル予報＝初期値を少し変えた多数の計算で不確かさを見積もる
★スプレッド小＝信頼度高、スプレッド大＝信頼度低`,
