・コンピュータの計算能力が向上するにつれて、数値予報モデルの水平格子間隔は徐々に細かくなり、より小さなスケールの現象を直接表現できるようになってきた
・格子間隔が粗い時代には、低気圧や前線のような総観規模の現象の表現が中心だったが、格子が細かくなるにつれて、線状降水帯のようなメソスケールの現象も、ある程度直接的に表現できるようになってきている
