・前日に雨が降った後の晴天・強風日は、たまっていた花粉が一気に飛散しやすく、花粉の飛散量が特に多くなりやすいといわれる
・移動性高気圧（既習）に覆われて晴れて気温が上がりやすい春の気圧配置は、花粉が飛散しやすい気象条件と重なりやすい

