        id: 'antei-02',
        title: 'CAPEとCIN：積乱雲のアクセルとブレーキ',
        emoji: '🔋',
        body: `▼ゼロから
炭酸のペットボトルは、フタ（栓）があるから吹きこぼれません。でも中の圧力（エネルギー）が大きいほど、フタを開けた瞬間は激しく噴き出します。大気も同じで、CAPEは「噴き出すエネルギー」、CINは「フタの固さ」。フタが固いのに中身がパンパンな日ほど、いったん対流が始まると猛烈な積乱雲になります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 CAPE（対流有効位置エネルギー）
━━━━━━━━━━━━━━━━━━━━━━
・持ち上げた空気塊が「まわりより暖かい」区間（自由対流高度LFC〜平衡高度EL）で得られる浮力エネルギーの合計
・エマグラム上では、状態曲線と空気塊の経路に囲まれた正の面積
・単位：J/kg
・目安：1000前後で雷雨に注意、2500以上は激しい現象への警戒（数値はあくまで目安）

【図解】CAPEをエマグラムで見る
・地上からLFC（自由対流高度、ここから浮力プラス）までは、空気塊がまわりより冷たい面積＝CIN
・LFCからEL（ここで浮力ゼロになる高さ）までは、空気塊がまわりより暖かい面積＝CAPE
→ 面積が広いほどエネルギー大＝上昇流が強くなれる
→ CAPEが大きいほど雲頂は高く、ひょう・激しい雷雨の可能性

━━━━━━━━━━━━━━━━━━━━━━
🔑 CIN（対流抑制）
━━━━━━━━━━━━━━━━━━━━━━
・地上からLFCまでの「まわりより冷たい」区間で必要な持ち上げエネルギー
・CINが大きい＝フタが固い＝積乱雲がなかなか発生しない
・フタの正体は逆転層や安定層（沈降性逆転層など）であることが多い

【図解】CAPE×CINの4パターン
　　　　　CIN小（フタ弱）　CIN大（フタ固）
CAPE大　すぐ雷雨に　　　　「ため込み型」
　　　　（午後随時発生）　　夕方一気に爆発しがち
CAPE小　弱い にわか雨程度　対流はほぼ起きない
→ 一番怖いのは「CAPE大×CIN大」：昼間はよく晴れて
　エネルギーをため、夕方フタが破れて猛烈な雷雨に

━━━━━━━━━━━━━━━━━━━━━━
🔑 対流のきっかけ（トリガー）
━━━━━━━━━━━━━━━━━━━━━━
CINというフタを破るきっかけ：
・日射による地表加熱（午後の熱雷）
・山の斜面の強制上昇（山岳部の雷雨）
・前線・シアーライン・海風前線での収束
・上空の気圧の谷の接近（上昇流の強化）
→ 「不安定＋トリガー」がそろって初めて積乱雲が発生する

【図解】夏の1日のCAPE・CINの推移（典型例）
朝：地表はまだ冷たい　CAPE小・CIN大 → 快晴
昼：日射で下層が加熱　CAPE増大・CIN縮小 → 積雲ぽつぽつ
午後2〜5時：CAPE最大・CINほぼ消滅 → 熱雷のゴールデンタイム
夜：地表冷却でCAPE減 → 雷雨はしだいに衰弱
→ 「夕立が午後に多い」のはCAPEとCINの日変化そのもの
→ 夜でも下層に暖湿気が流入し続ければ夜間の雷雨もあり得る

━━━━━━━━━━━━━━━━━━━━━━
🔑 ほかの安定度指数との関係
━━━━━━━━━━━━━━━━━━━━━━
・SSI（ショワルター安定指数）：850hPaから500hPaへの持ち上げで判定。マイナスほど不安定
・K指数：気温減率と下層の湿りを組み合わせた指数。大きいほど雷雨の可能性が高い
・CAPE：エネルギーの総量そのものを面積で評価
→ 1つの指数だけで決めつけず、複数の指数＋実況で総合判断するのがプロの流儀

⚠ ひっかけ注意
・CAPEが大きくても、CINが大きくトリガーがなければ積乱雲は発生しない
・CAPEはエネルギーの「量」であり、発生の「時刻・場所」までは教えてくれない
・CINは悪者ではない：CINがあるおかげで毎日どこでも雷雨にはならない
・LFCが高い（フタが厚い）日は発生しにくいが、発生すれば激しくなりやすい

★ここだけ暗記
★CAPE＝LFCからELまでの正の浮力の面積（J/kg）＝アクセル
★CIN＝LFCより下の負の浮力＝フタ（ブレーキ）
★発生の条件＝不安定（CAPE）×フタ破り（トリガー）
★「CAPE大×CIN大」は夕方に爆発的雷雨のパターン`,
