        emoji: '🌁',
        body: `▼ゼロから
「霧」とひとことで言っても、生まれ方はいろいろです。放射冷却で生まれる霧、暖かい空気が冷たい海面上を流れて生まれる霧、山の斜面を空気が上って生まれる霧——ここまでの章で少しずつ登場してきた霧の仲間たちを、まとめて整理しましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 霧の正体：地表付近にできる雲
━━━━━━━━━━━━━━━━━━━━━━
・霧は、地表付近の空気が冷やされる、あるいは水蒸気が加わることで飽和に達し、既習の雲と同じしくみ（凝結核のまわりに水滴ができる）で地表付近に微小な水滴が浮遊した状態
・「雲」と「霧」は本質的に同じ現象であり、地表に接しているかどうかが呼び方の違いにすぎない

━━━━━━━━━━━━━━━━━━━━━━
🔑 霧の種類とできる仕組み（総整理）
━━━━━━━━━━━━━━━━━━━━━━
① 放射霧：既習のとおり、よく晴れて風が弱い夜、放射冷却によって地表付近の気温が露点まで下がることで発生する（既習の接地逆転層とセット）。盆地では既習の冷気湖の中で特に濃くなりやすい
② 移流霧：既習のとおり、暖かく湿った空気が、より冷たい海面や地表の上を移動する際に、下から冷やされて発生する。既習の親潮域での発生などが代表例
③ 滑昇霧（上昇霧）：湿った空気が山の斜面に沿って上昇し、既習の断熱冷却によって露点に達することで発生する霧
④ 蒸気霧：冷たい大気の下に、より暖かい水面（湖や川など）がある場合、水面からの蒸発で水蒸気が供給され、それが冷たい空気にすぐ冷やされて発生する霧。冬の水面から湯気のように立ちのぼって見える

【図解】霧の4タイプの原因の整理
放射霧　：地表が冷える（放射冷却）→ 接地逆転層とセット
移流霧　：暖湿な空気が冷たい面の上を移動 → 下から冷やされる
滑昇霧　：湿った空気が斜面を上昇 → 断熱冷却で露点に達する
蒸気霧　：冷たい空気の下の暖かい水面から水蒸気が供給される
→ 「冷える理由」がそれぞれ異なる点を軸に整理すると覚えやすい

━━━━━━━━━━━━━━━━━━━━━━
🔑 霧が発生・解消しやすい条件のまとめ
━━━━━━━━━━━━━━━━━━━━━━
・放射霧は、既習のとおり晴天・弱風・空気の乾燥（放射冷却が進みやすい条件）がそろう夜間〜早朝に発生しやすく、日中の日射で地表が温まると下から解消していく
・移流霧は、暖湿な空気の移流が続く限り持続しやすく、風向・風速が変わって暖湿な空気の供給が止まると解消に向かう
・霧は視程を著しく悪化させ、交通機関（航空・海上交通など）に大きな影響を与えるため、視程観測（既習）による監視が重要になる

⚠ ひっかけ注意
・霧と雲は本質的に同じ現象であり、地表に接しているかどうかが呼び方の違いにすぎない
・放射霧は「日中」ではなく、放射冷却が進む「夜間〜早朝」に発生しやすい
・移流霧は「地表の冷却」ではなく、「暖湿な空気が冷たい面の上を移動すること」が発生の主因である
・蒸気霧は、暖かい空気ではなく「冷たい空気の下に相対的に暖かい水面がある」状況で発生する点に注意（他の霧と成因が逆）

★ここだけ暗記
★霧＝地表付近にできる雲。放射霧・移流霧・滑昇霧・蒸気霧の4タイプに整理できる
★放射霧＝地表の放射冷却（接地逆転層とセット）、移流霧＝暖湿な空気が冷たい面上を移動
★滑昇霧＝湿った空気の断熱冷却（斜面上昇）、蒸気霧＝冷気の下の暖かい水面からの蒸発
★霧は視程を著しく悪化させ、交通機関への影響が大きいため監視が重要`,
