「前線」と一口に言っても、断面を見ると個性がはっきり分かれます。傾きが急でパワフルな寒冷前線、なだらかで広範囲に雨を降らせる温暖前線、2階建て構造の閉塞前線。断面図を自分で描けるようになると、実技の記述問題が一気に楽になります。

━━━━━━━━━━━━━━━━━━━━━━
