        emoji: '🌪️',
        body: `▼ゼロから
地上の低気圧が発達するかどうかは、実は「上空」で決まります。上空5500m（500hPa）の気圧の谷（トラフ）が地上の低気圧の西側にあるとき、低気圧は発達します。「なぜ西側だと発達するのか」を渦度と上昇流で説明できれば、学科専門も実技も一段上のレベルに到達です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 渦度：回転の強さを表す数値
━━━━━━━━━━━━━━━━━━━━━━
・渦度＝空気の回転の強さと向きを表す量
・北半球では反時計回り（低気圧性）が正、時計回り（高気圧性）が負
・500hPa天気図には渦度の分布が描かれ、トラフには正渦度の極大が対応
・風のシアー（横方向の風速差）でも渦度は生じる：ジェット気流の北側は正渦度、南側は負渦度

【図解】渦度の正負のイメージ（北半球）
正の渦度（＋）：反時計回り ↺　　低気圧・トラフに対応
負の渦度（−）：時計回り　 ↻　　高気圧・リッジに対応
ジェット軸　══════▶（強風帯）
　北側：反時計回りのシアー → 正渦度
　南側：時計回りのシアー → 負渦度
→ 「曲がり」と「風速差」の2つが渦度を作る

━━━━━━━━━━━━━━━━━━━━━━
🔑 正渦度移流と上昇流
━━━━━━━━━━━━━━━━━━━━━━
・トラフの前面（東側）では、風が正渦度の大きい領域から小さい領域へ吹く＝「正渦度移流」
・上空で正渦度移流があると、その下層で空気の吸い上げ（上昇流）が誘発される
・上昇流の場所では雲が湧き、地上の気圧が下がりやすい

【図解】トラフと地上低気圧の黄金配置
上空500hPa：　　トラフ（正渦度極大）
　　　　　　　　　＼
　　　　　　　　　　＼（西に傾いた軸）
地上：　　　　　　　　（L）地上低気圧
　　　　　　西　◀──────▶　東
○発達期：上空のトラフが地上のLの「西」にある（軸が西に傾く）
　→ 地上Lの真上で正渦度移流・上昇流 → どんどん発達
×トラフと地上Lが重なる（軸が立つ）→ 発達終了・最盛期〜衰弱
→ 「軸の傾き」で低気圧の発達段階を診断できる！

━━━━━━━━━━━━━━━━━━━━━━
🔑 発達をあと押しする条件（総合診断）
━━━━━━━━━━━━━━━━━━━━━━
・上空：トラフ接近・正渦度移流・ジェット気流の出入口の発散域
・下層：暖気移流（南風で暖気が流入）と寒気移流の対比が明瞭
・海面：暖流上（黒潮など）では下層に熱・水蒸気が補給され発達を強化
→ 冬の日本の南岸・三陸沖は爆弾低気圧の多発地帯

【図解】爆弾低気圧（急速に発達する低気圧）
定義の目安：中心気圧が24時間で約24hPa以上低下
　（緯度60度換算。緯度により補正）
実例パターン：
　冬、日本の南岸で発生 → 三陸沖で急発達
　→ 全国で暴風・高波・大雪・猛吹雪
→ 「台風並み」の暴風を冬にもたらす危険な存在

⚠ ひっかけ注意
・「トラフの真下で低気圧が発達」は×。発達するのはトラフの前面（東側）
・発達期の低気圧の軸は「上空ほど西に傾く」。軸が立つと発達は頭打ち
・正渦度移流は「上空」の話。地上でも渦度はあるが、診断に使うのは主に500hPa
・爆弾低気圧は俗称的な用語で、24時間24hPa（緯度補正あり）は目安の定義

★ここだけ暗記
★北半球：反時計回り＝正渦度、時計回り＝負渦度
★トラフ前面（東側）＝正渦度移流→上昇流→地上低気圧発達
★発達期の低気圧は軸が西に傾く（上空のトラフが西）
★急速発達の目安：24時間で約24hPa低下（緯度60度基準）`,
