        body: `▼ゼロから
実技試験では、白紙の天気図に自分で前線を描き込む問題が出ます。「なんとなくこの辺」ではなく、複数の観測要素を根拠に位置を絞り込む手順を持っていることが得点の分かれ目です。ここでは前線の位置を決めるための着眼点をチェックリスト化します。

━━━━━━━━━━━━━━━━━━━━━━
🔑 前線の位置を決める5つの手がかり
━━━━━━━━━━━━━━━━━━━━━━
① 気温：前線をはさんで気温が急に変わる境目を探す（等温線の集中帯）
② 風向：前線の前後で風向が明瞭に変化する場所（シアーライン）
③ 気圧：等圧線が「キンク（折れ曲がり）」している場所は前線が通っていることが多い
④ 雲・降水：雲域や降水域の縁（特に寒冷前線側は雲の切れ目がはっきりすることが多い）
⑤ 相当温位：850hPa等相当温位線が混み合う帯（集中帯）は前線帯の目安

【図解】5つの手がかりを重ね合わせて前線位置を絞り込む
・等温線の集中帯
・風向シアーライン
・等圧線のキンク
・雲域・降水域の縁
これらがおおむね同じ場所に集中する → その重なりが前線の位置
→ 1つの手がかりだけで決めず、複数が一致する場所を選ぶのが鉄則

━━━━━━━━━━━━━━━━━━━━━━
🔑 前線の種類を見分ける実技的な着眼点
━━━━━━━━━━━━━━━━━━━━━━
【図解】温暖前線か寒冷前線かの判定チェック
□ 前線の前面（進行方向側）に広い雨域が広がっているか → 温暖前線寄り
□ 前線付近〜後面に狭く強い雨域・雷を伴うか → 寒冷前線寄り
□ 通過後に気温が上がるか下がるか（前後の気温データを比較）
□ 風向の変化が「南寄り→北寄り」で急変しているか（寒冷前線の目安）
→ チェックが多く当てはまる方の前線タイプを選ぶ

【図解】停滞前線か判定するときの着眼点
□ 前線の位置が数日間ほとんど動いていないか（複数時刻の天気図を比較）
□ 前線をはさんだ両側の気団の勢力（高気圧の強さ）が拮抗しているか
□ 前線に伴う雨域が同じ場所にかかり続けているか
→ 動いていない・両側が拮抗＝停滞前線（梅雨・秋雨前線の可能性）

━━━━━━━━━━━━━━━━━━━━━━
🔑 前線解析の実技演習フロー
━━━━━━━━━━━━━━━━━━━━━━
① 地上天気図の等圧線のキンクを探し、前線のおおまかな候補ラインを引く
② 850hPa天気図の等温線・等相当温位線の集中帯と候補ラインを重ね合わせる
③ 気象衛星画像・レーダー画像の雲域・降水域の縁と照合する
④ 前後の観測点の気温・風向・天気の変化から前線の種類を判定する
⑤ 前線記号（半円・三角・向き）を記入する
→ ①〜⑤の順で「地上→高層→衛星→観測」と視点を広げるのが実技の型

⚠ ひっかけ注意
・等圧線のキンクだけで前線と決めつけない。気温・風向のデータと必ず照合する
・850hPaの前線帯（相当温位集中帯）と地上前線の位置は完全には一致しない（地上前線はやや暖気側にずれることが多い）
・停滞前線でも活動が強まれば大雨になる。「動かない＝弱い」と早合点しない
・前線の種類判定は複数の手がかりの総合判断。1つの要素（例えば風向だけ）で断定しない

★ここだけ暗記
★前線位置の5つの手がかり：気温・風向・気圧のキンク・雲/降水の縁・相当温位集中帯
★複数の手がかりが重なる場所を前線位置として選ぶ（1手がかりで即断しない）
★実技の型：地上のキンク→850hPaの集中帯→衛星/レーダー→観測データの順に照合
★停滞前線は「動かない・両気団が拮抗」がサイン。活動の強弱は別問題`,
