・気象予報士の名称を無資格で用いることについても、法令上の規制の対象となりうる
・罰則の対象となる行為の種類（無許可営業、名称の不正使用、虚偽の警報類似情報の発表など）は複数あり、それぞれに応じた規定が定められている
