・地上天気図に目立った低気圧・前線がないにもかかわらず、大気の状態が不安定である（既習の安定度指数が不安定を示す）場合、上空の寒冷渦の存在を疑う視点を持つ
・寒冷渦は動きが遅いため、同じ地域で数日にわたり不安定な天気が繰り返される場合、その背景に寒冷渦が居座っている可能性を検討する

