        body: `▼ゼロから
台風の被害というと強風や大雨をイメージしがちですが、沿岸部で最も命に関わるのは「海水が街へ押し寄せる」高潮です。高潮は「気圧が下がって海面が持ち上がる効果」と「強い風が海水を吹き寄せる効果」の合わせ技で起こります。しくみを分解して、実技での計算にも対応できるようにしましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 高潮を起こす2つの効果
━━━━━━━━━━━━━━━━━━━━━━
① 吸い上げ効果：気圧が下がると、その分だけ海面を押さえつける力が弱まり、海面が持ち上がる
　目安：気圧が標準より1hPa下がるごとに、海面はおよそ1cm上昇する
② 吹き寄せ効果：強い風が海岸に向かって吹き続けると、海水が岸へ吹き寄せられて海面が高くなる
　・遠浅で奥まった湾（湾の形が風を受けやすい向き）ほど効果が大きくなりやすい
　・吹き寄せの高さは風速のおおむね2乗に比例して大きくなる関係があり、強風になるほど急激に効果が増す

【図解】台風による高潮のしくみ
① 気圧低下（例：標準より40hPa低い）
　→ 吸い上げ効果でおよそ40cm程度の海面上昇（1hPaあたり約1cmの目安）
② 強風が海岸に吹き寄せる
　→ 吹き寄せ効果でさらに海面が持ち上がる（風速が強いほど急激に効く）
③ ①＋②が満潮の時刻と重なると、潮位はさらに高くなる
→ 「気圧・風・潮汐」の3つが重なるタイミングが最も危険

━━━━━━━━━━━━━━━━━━━━━━
🔑 計算ドリル：吸い上げ効果の見積もり
━━━━━━━━━━━━━━━━━━━━━━
【図解】気圧の計算例
問題：標準気圧1013hPaの海域に、中心気圧960hPaの台風が接近した。吸い上げ効果によるおおよその海面上昇量を求めよ。
① 気圧差＝1013−960＝53hPa
② 1hPaあたり約1cmの目安を使うと、上昇量 ≒ 53cm
→ 実際にはこれに吹き寄せ効果が加わるため、想定される高潮はさらに大きくなりうる

━━━━━━━━━━━━━━━━━━━━━━
🔑 高潮の被害が大きくなりやすい地形・タイミング
━━━━━━━━━━━━━━━━━━━━━━
・遠浅で湾の奥が狭くなる形状の湾（過去に高潮被害が繰り返されてきた大きな湾に多い地形的特徴）は、海水が行き場を失い水位が上昇しやすい
・満潮（特に大潮の満潮）の時刻に台風の接近が重なると、高潮の潮位がさらにかさ上げされる
・台風の進行方向の右側（危険半円）にあたる沿岸では、台風自身の進行速度が加わって風が強まりやすく、吹き寄せ効果も強まりやすい

【図解】高潮リスクが重なる「最悪のタイミング」
台風接近のタイミング × 満潮（特に大潮）のタイミング × 危険半円側の強風
→ 3つが重なると、想定を超える高い潮位になるおそれがある
→ 防災上は「気圧の低さ」だけでなく「風向・地形・潮汐表」もあわせて確認する

━━━━━━━━━━━━━━━━━━━━━━
🔑 高波・うねりと台風
━━━━━━━━━━━━━━━━━━━━━━
・台風の強風域では、風によって高い波（風浪）が発生する
・台風本体から離れた海域でも、台風が作った波が長い周期の「うねり」として伝わってくることがあり、台風が接近する前から海が荒れることがある
・波の高さは風速だけでなく、風が吹く距離（吹走距離）や吹き続ける時間にも左右される

⚠ ひっかけ注意
・「気圧が低いほど高潮が起きる」だけでは不十分。吹き寄せ効果（風）と潮汐のタイミングも合わせて考える必要がある
・1hPaあたり約1cmはあくまで目安。実際の海面上昇量は海底地形・湾の形状などにも左右される
・「満潮でなければ高潮の心配はない」は×。満潮でなくても危険な水位になることはある（重なるとさらに危険というだけ）
・うねりは台風から遠く離れた海岸にも、台風接近の前触れとして到達することがある

★ここだけ暗記
★高潮＝吸い上げ効果（気圧低下、目安1hPaで約1cm）＋吹き寄せ効果（強風、風速の2乗的に増大）
★危険が重なるタイミング＝台風接近×満潮（大潮）×危険半円側の強風
★遠浅で奥が狭い湾は高潮の水位が上がりやすい地形
★台風のうねりは本体が遠くても先行して沿岸に到達することがある`,
