        body: `▼ゼロから
発達した台風の中心には、雲のない静かな「眼」があり、そのまわりを最も激しい風雨をもたらす「壁雲（アイウォール）」が取り巻いています。実はこの壁雲、1つだけとは限りません。発達した台風では、壁雲が二重になり、内側の壁雲が外側の壁雲に置き換わっていく不思議な周期が見られることがあります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 台風の眼と壁雲の構造（おさらい）
━━━━━━━━━━━━━━━━━━━━━━
・眼：台風の中心付近にできる、比較的雲が少なく風も弱い領域。中心では下降流が卓越し、周辺の壁雲とは対照的な穏やかな状態になる
・壁雲（アイウォール）：眼を取り巻くように発達した、背の高い積乱雲の輪。台風の中で最も強い風・雨をもたらす領域
・眼の大きさや壁雲の形は、台風の勢力や発達段階によって変化する

【図解】台風の眼と壁雲の断面（模式）
　　　外側　　　壁雲（強風・強雨）　　　眼（静穏・下降流）　　　壁雲　　　外側
　　　←────────壁雲の輪が眼を取り巻く────────→
→ 「静かな中心」と「最も激しい輪」が同居する台風特有の構造

━━━━━━━━━━━━━━━━━━━━━━
🔑 眼の壁雲置換周期（ERC）とは
━━━━━━━━━━━━━━━━━━━━━━
・非常に発達した台風では、既存の壁雲（内側壁雲）の外側に、新たな壁雲（外側壁雲）が形成され、二重の壁雲構造になることがある
・外側壁雲が発達するにつれて、内側壁雲は水蒸気・エネルギーの供給を奪われる形で弱まり、最終的に消滅する
・内側壁雲が消滅した後、外側壁雲がその役割を引き継ぎ、新しい（一回り大きな）壁雲として台風の眼を取り巻くようになる。この一連の変化を眼の壁雲置換周期（アイウォール・リプレイスメント・サイクル、ERC）と呼ぶ

【図解】眼の壁雲置換周期の流れ
① 内側壁雲（既存）のみの状態
　↓
② 外側に新たな壁雲（外側壁雲）が形成され、二重壁雲構造に
　↓
③ 内側壁雲が弱まり消滅、眼が一回り大きくなる
　↓
④ 外側壁雲が新たな壁雲として台風を取り巻く（眼のサイズが変化した状態で安定）
→ 「内側が外側に置き換わる」プロセスがERCの本質

━━━━━━━━━━━━━━━━━━━━━━
🔑 ERCが台風の勢力に与える影響
━━━━━━━━━━━━━━━━━━━━━━
・ERCの進行中は、内側壁雲の力学的な構造が崩れることに伴い、台風の最大風速が一時的に弱まることが多いとされる
・ERCが完了し、外側壁雲が新しい壁雲として確立すると、眼の直径が一回り大きくなった状態で、台風が再び強まることもある
・そのため、ERCの最中の台風の強度変化（弱まったように見える段階）を見て「もう衰弱している」と早合点しないよう注意が必要である

⚠ ひっかけ注意
・ERCの最中に見られる一時的な弱まりは、必ずしも台風が最終的に衰弱していくことを意味しない（再強化することもある）
・二重壁雲構造は、必ずすべての台風で見られるわけではなく、非常に発達した台風で確認されやすい現象である
・ERCが起こると眼の大きさが変化することがあり、「眼の大きさ＝台風の勢力の強さ」と単純に結びつけるのは不正確
・ERCは衛星画像や航空機観測、レーダーなどによって確認される現象であり、地上の観測だけから直接判断することは難しい

★ここだけ暗記
★眼の壁雲置換周期（ERC）＝非常に発達した台風で、外側に新しい壁雲ができ内側壁雲と置き換わる現象
★ERCの進行中は最大風速が一時的に弱まることが多いが、完了後に再強化することもある
★二重壁雲構造は非常に発達した台風で見られやすい
★ERC中の弱まりだけを見て台風が衰弱したと早合点しない`,
