        emoji: '🌊',
        body: `▼ゼロから
台風による災害は、高潮だけ、大雨だけと単独で起こるとは限りません。海からの高潮と、川からの大雨による増水が同時に襲いかかる「複合災害」は、被害をさらに深刻化させます。海と川、2つの水の脅威が重なるとき何が起こるのかを見ていきましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 高潮と河川の増水が重なる状況
━━━━━━━━━━━━━━━━━━━━━━
・台風の接近時には、既習の高潮（海面の上昇）と、大雨による河川の増水が同時に、あるいは前後して発生することが多い
・河口付近では、川を流れる水が海へ出ていく出口の水位（海面の高さ）そのものが高潮によって高くなるため、川の水がスムーズに海へ流れ出にくくなり、内陸側での水位上昇（バックウォーター現象と呼ばれる、下流側の水位上昇の影響が上流側にまで及ぶ現象）が助長されることがある
・満潮（既習）と河川のピーク流量のタイミングが重なると、河口付近の水位はさらに高くなりやすい

【図解】高潮が河川の水はけを悪くする仕組み（河口付近の模式）
平常時：川の水　→　海へスムーズに流出
高潮時：海面が高い　→　川の水が出ていきにくくなる（せき止められる）
　　　　→　河口付近・その上流側で水位が上昇しやすくなる
→ 「海の水位が、川の水はけの良し悪しを左右する」という、海と川のつながり

━━━━━━━━━━━━━━━━━━━━━━
🔑 複合災害が被害を深刻化させる理由
━━━━━━━━━━━━━━━━━━━━━━
・高潮単独、あるいは河川の増水単独であれば対応できる規模の水位でも、両者が重なることで、想定を超える浸水範囲・浸水の深さになることがある
・低地・ゼロメートル地帯（海面より低い土地）が広がる沿岸部では、いったん浸水すると排水が難しく、浸水が長期間続くことがある
・避難のタイミングも、高潮・河川増水それぞれの防災情報（既習のキキクル、指定河川洪水予報など）を総合的に確認する必要があり、単独の情報だけでは危険性を見落とすことがある

【図解】複合災害への総合的な備えの視点
台風情報（進路・強さ）
　＋
高潮の要素（気圧低下・風向地形・満潮タイミング、既習）
　＋
河川の増水の要素（上流域の降水量、既習の流域雨量指数など）
　↓
総合的に沿岸・河口付近の水位上昇リスクを評価する
→ 「海」と「川」を別々ではなく、一体として捉える視点が防災上重要

━━━━━━━━━━━━━━━━━━━━━━
🔑 実技・防災での複合災害の捉え方
━━━━━━━━━━━━━━━━━━━━━━
・台風接近時の記述問題では、高潮の要因（既習）と大雨・河川増水の要因を、それぞれ別個に説明するだけでなく、河口付近ではこの2つが重なりうる点にも触れられると、より深い理解を示す解答になる
・防災上は、沿岸部・河口付近に住む場合、高潮と河川氾濫の両方のハザードマップ・防災情報を確認しておくことが望ましいとされる

⚠ ひっかけ注意
・高潮と河川の増水は無関係な別々の現象ではなく、河口付近では互いに影響し合う（高潮が河川の水はけを悪くする）関係にある
・「高潮の心配がないから河川も安全」「河川の増水がおさまったから安心」のように、片方だけを見て判断するのは危険
・複合災害への備えは、台風情報・高潮の要素・河川増水の要素を総合的に確認することが基本
・満潮のタイミングと河川のピーク流量のタイミングが重なると、河口付近の水位上昇リスクはさらに高まる

★ここだけ暗記
★河口付近では、高潮による海面上昇が河川の水はけを悪くし、内陸側の水位上昇を助長することがある
★高潮単独・河川増水単独では対応できる規模でも、重なると被害が深刻化しうる（複合災害）
★満潮と河川のピーク流量のタイミングの重なりが、河口付近のリスクをさらに高める
★防災の記述・実務では、海（高潮）と川（河川増水）を一体として総合的に評価する視点が重要`,
