        body: `▼ゼロから
「警報が出ています」と言われても、自分の家が危ないのかどうかは分かりません。そこで生まれたのが、地図を色分けして「どこが」危ないかをひと目で示すキキクル（危険度分布）。天気版のハザード信号機です。仕組みを知ると、警報の文字情報が立体的に読めるようになります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 キキクルとは
━━━━━━━━━━━━━━━━━━━━━━
・土砂キキクル（土砂災害）・浸水キキクル（浸水害）・洪水キキクル（洪水災害）の3種類
・雨量の実況と予測から計算した指数を使い、危険度を地図上に色で表示
・約1km四方（洪水は河川ごと）のきめ細かさで、10分ごとに更新

【図解】キキクルの色の階段
黒 　　：災害切迫（すでに発生していてもおかしくない）
うす紫　：危険（避難完了しているべき段階の目安）
赤　　　：警戒（警報級・高齢者等は避難）
黄　　　：注意（注意報級）
無色　　：情報なし
→ 「黄→赤→うす紫→黒」の順で危険度アップ
→ うす紫までに避難を終えるのが原則。黒を待たない！

━━━━━━━━━━━━━━━━━━━━━━
🔑 危険度を支える3つの指数
━━━━━━━━━━━━━━━━━━━━━━
・土壌雨量指数：降った雨が土の中にどれだけたまっているかをタンクモデルで計算 → 土砂災害
・表面雨量指数：地表にあふれる雨のたまりやすさ（都市の舗装なども考慮）→ 浸水害
・流域雨量指数：川の上流に降った雨が流れ下って集まる量 → 洪水災害

【図解】土壌雨量指数のタンクモデル
雨が降ると、3段に重なったタンクに水がたまっていく
・タンク1（浅い土）：水位＝たまった水。横穴から表面流出、下に浸透
・タンク2（深い土）：タンク1から浸透した水がたまり、横穴から流出
・タンク3（さらに深い土）：タンク2から浸透した水がたまる
→ 3段のタンクの水位の合計が土壌雨量指数
→ 雨がやんでも水はすぐ抜けない＝危険は雨の後も続く！

【図解】キキクル活用の3ステップ
① 大雨のおそれ → 警報・注意報で「時間帯」を把握
② キキクルで「自分の場所」の色を確認（10分ごと更新）
③ 色が赤〜うす紫に近づいたら、ハザードマップと避難情報で行動
→ 「面的な危険度」＋「自分の位置」の重ね合わせが防災の基本

⚠ ひっかけ注意
・キキクルの「黒」は避難開始の合図ではない。すでに手遅れの可能性がある段階
・土壌雨量指数は雨がやんでもすぐ下がらない → 晴れてからの土砂災害もある
・洪水キキクルは大河川だけでなく中小河川の危険度も対象
・キキクルは「予測を含む」情報。実況レーダーの雨の強さとは別物

★ここだけ暗記
★キキクル3種：土砂・浸水・洪水（約1kmメッシュ・10分更新）
★指数の対応：土壌→土砂災害、表面→浸水害、流域→洪水
★色：黄（注意）→赤（警戒）→うす紫（危険）→黒（災害切迫）
★土壌雨量指数は雨がやんでも高いまま→事後の土砂災害に注意`,
