━━━━━━━━━━━━━━━━━━━━━━
・土砂災害警戒情報：大雨警報発表中に土砂災害の危険度がさらに高まったとき、都道府県と気象庁が共同で発表（レベル4相当）
・記録的短時間大雨情報：その地域で数年に一度程度の記録的な1時間雨量（おおむね80〜120mm、府県ごとの基準）を観測・解析したときに発表。「今まさに災害級の雨が降った」ことを知らせる

