・特別警報が発表された段階は「今から避難を始める」タイミングではなく、「すでに避難を終えているべき」極めて切迫した段階である
・特別警報は気象現象だけでなく、地震・火山・津波など、気象庁が扱う幅広い分野にまたがる枠組みとして存在する
・特別警報が発表されていないからといって、警報級の現象による危険がないわけではない（警報の段階でも十分に警戒が必要）

