        body: `▼ゼロから
「天気予報はよく外れる」は本当でしょうか？ 印象論で語らないために、予報の世界では成績を必ず数字で検証します。基本の道具は、テストの丸付け表のような「2×2の分割表」。ここから適中率・見逃し率・空振り率などの指標が生まれます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 分割表：検証のスタート地点
━━━━━━━━━━━━━━━━━━━━━━
【図解】雨予報の2×2分割表
　　　　　　　実況：雨あり　実況：雨なし
予報：雨あり　　A（適中）　　B（空振り）
予報：雨なし　　C（見逃し）　D（適中）
・A＝雨と予報して雨が降った
・B＝雨と予報したが降らなかった（空振り）
・C＝降らないとしたのに降った（見逃し）
・D＝降らない予報で実際に降らなかった
→ すべての検証指標はこのA・B・C・Dの組み合わせ

━━━━━━━━━━━━━━━━━━━━━━
🔑 基本の指標
━━━━━━━━━━━━━━━━━━━━━━
・適中率＝（A＋D）÷ 全体（A＋B＋C＋D）
・空振り率＝B ÷（A＋B）…雨予報のうち外れた割合（分母の取り方は問題文の定義に従う）
・見逃し率＝C ÷（C＋D）…雨なし予報のうち降ってしまった割合（同上）
・捕捉率＝A ÷（A＋C）…実際の雨をどれだけ捉えたか

【図解】計算練習（数値例）
100日のうち：A=20、B=10、C=5、D=65
・適中率＝(20+65)/100＝85%
・捕捉率＝20/(20+5)＝80%
・空振り率＝10/(20+10)≒33%
→ 分割表さえ書ければ、あとは割り算するだけ

━━━━━━━━━━━━━━━━━━━━━━
🔑 見逃しと空振りのトレードオフ
━━━━━━━━━━━━━━━━━━━━━━
・見逃し（C）を減らしたい → 雨予報を増やす → 空振り（B）が増える
・空振りを減らしたい → 雨予報を絞る → 見逃しが増える
→ 両方同時にゼロにはできない。防災上は「見逃し」の方が重大なので、警報などはやや空振りを許容する設計になっている

【図解】予報のさじ加減シーソー
雨予報を増やす　◀────────▶　雨予報を絞る
見逃し減・空振り増　　　　　　見逃し増・空振り減
（防災重視）　　　　　　　　　（オオカミ少年回避）
→ どちらに倒すかは「外したときの損害の大きさ」で決める

━━━━━━━━━━━━━━━━━━━━━━
🔑 確率予報の検証：ブライアスコア
━━━━━━━━━━━━━━━━━━━━━━
・降水確率のような確率予報の成績表
・（予報確率 − 実況(降れば1、降らなければ0)）の2乗を平均した値
・0に近いほど良い予報。完全予報なら0
・「70%と言った日の7割で実際に降る」なら信頼度の高い確率予報

⚠ ひっかけ注意
・適中率が高くても良い予報とは限らない（滅多に雨が降らない砂漠で毎日「晴れ」と言えば適中率は高くなる）
・空振り率・見逃し率は分母の定義が複数流儀ある。問題文の定義に必ず従う
・ブライアスコアは小さいほど良い（大きいほど良い、と逆にしない）
・見逃しと空振りはトレードオフ。「両方減らせる」という選択肢は疑う

★ここだけ暗記
★分割表：A適中・B空振り・C見逃し・D適中
★適中率＝(A＋D)/全体、捕捉率＝A/(A＋C)
★見逃しと空振りはトレードオフの関係
★ブライアスコア＝確率予報の検証指標。0に近いほど良い`,
