        body: `▼ゼロから
未来がひとつに決められないなら、「あり得る未来を全部計算してしまえ」というのがアンサンブル予報の発想です。天気予報版のシミュレーションゲームを何十回もプレイして、結果のばらつき具合から「予報の自信度」まで数値化します。週間予報の信頼度A・B・Cの正体はこれです。

━━━━━━━━━━━━━━━━━━━━━━
🔑 アンサンブル予報のしくみ
━━━━━━━━━━━━━━━━━━━━━━
・初期値に観測誤差程度の小さな「ゆらぎ」を与えた多数のメンバーを計算
・モデルの不完全さを考慮する手法を組み合わせることもある
・平均（アンサンブル平均）は個々のメンバーより誤差が小さくなる傾向
・ばらつき（スプレッド）は予報の不確かさの目安になる

【図解】スパゲッティ図のイメージ（台風進路の例）
メンバー1：　＼
メンバー2：　　＼＿
メンバー3：　＼＿＿
…51本の線が束になって伸びる
・線が束のようにまとまる → スプレッド小 → 信頼度高
・線が扇形に広がる → スプレッド大 → 進路が定まらない
→ 予報円が大きくなるのはメンバーが広がっているとき

【図解】スプレッドと信頼度の関係
スプレッド小：未来の選択肢が少ない → 自信あり（信頼度A）
スプレッド中：ある程度ばらつく → 信頼度B
スプレッド大：未来があいまい → 信頼度C（予報が変わる可能性大）
→ 「予報が当たりやすいか」を予報できるのがアンサンブルの強み

━━━━━━━━━━━━━━━━━━━━━━
🔑 週間天気予報の信頼度A・B・C
━━━━━━━━━━━━━━━━━━━━━━
・週間予報の降水の有無の予報に付く3段階の信頼度
・A：確度が高い（予報が変わる可能性が低い）
・B：確度がやや高い
・C：確度がやや低い（予報が変わる可能性がある）
・一般に予報期間の後半ほどスプレッドが広がりCが増えやすい

━━━━━━━━━━━━━━━━━━━━━━
🔑 アンサンブルの活用先
━━━━━━━━━━━━━━━━━━━━━━
・週間天気予報・2週間気温予報・早期天候情報
・台風進路予報（予報円の大きさの根拠）
・季節予報（1か月・3か月・暖候期寒候期）：確率表現（高い・並・低い）で発表
→ 期間が長い予報ほど「決め打ち」せず確率・幅で伝える

【図解】予報期間と情報の出し方
明日：天気マークで断定的に（決定論的予報）
週間：信頼度A/B/C付きで
1か月：平年より高い/並/低いの確率（%）で
→ 先になるほど「幅を持った表現」に切り替わるのは
　 カオスの性質に合わせた科学的に正しい伝え方

⚠ ひっかけ注意
・アンサンブル平均は「メンバーの多数決の天気図」であり、細かい現象はならされて消える
・スプレッド大＝予報失敗ではない。「不確かさが大きい」という貴重な情報
・信頼度A・B・Cは降水の有無の予報に対する確度
・季節予報は「暑い/寒い」の断定ではなく3区分の確率で発表される

★ここだけ暗記
★アンサンブル予報＝初期値をわずかに変えた多数の計算
★スプレッド小→信頼度高、大→低（週間予報のA・B・C）
★アンサンブル平均は個々のメンバーより誤差が小さい傾向
★季節予報は「高い・並・低い」の確率で発表`,
