        title: 'ドップラーレーダーと二重偏波レーダー',
        emoji: '📡',
        body: `▼ゼロから
救急車のサイレンは、近づくとき高く、遠ざかると低く聞こえます（ドップラー効果）。同じ原理で、雨粒に当たって返ってくる電波の周波数のずれを測れば、雨粒が近づいているか遠ざかっているか——つまり「風」が分かります。レーダーは今や、雨の強さだけでなく風も粒の形も見抜く万能センサーです。

━━━━━━━━━━━━━━━━━━━━━━
🔑 レーダーの基本：エコーと Z-R関係
━━━━━━━━━━━━━━━━━━━━━━
・マイクロ波を発射し、降水粒子からの後方散乱（エコー）を受信
・戻るまでの時間 → 距離、エコーの強さ → 降水強度を推定
・レーダー反射因子Zは雨粒の直径の6乗に比例
　→ 少数の大粒でもエコーは非常に強くなる
・Zと降水強度Rの統計関係（Z-R関係）で雨の強さに換算するが、粒径分布によって誤差が出る → 雨量計と組み合わせて補正（解析雨量）

【図解】直径6乗の効き方
直径1mmの雨粒　　：Z ∝ 1
直径2mmの雨粒　　：Z ∝ 64（2の6乗）
直径4mmの雨粒　　：Z ∝ 4096（4の6乗）
→ 粒が倍になるとエコーは64倍！
→ 「エコーが強い＝粒が大きい可能性」も常に考える

━━━━━━━━━━━━━━━━━━━━━━
🔑 ドップラーレーダー
━━━━━━━━━━━━━━━━━━━━━━
・エコーの周波数偏移から、降水粒子の視線方向の速度（動径速度）を測定
・降水粒子は風に流されるので、実質的に風の場が分かる
・竜巻をもたらすメソサイクロン（積乱雲内の回転）の検出、低層の風の急変（シアー）の監視に活躍
・空港には低層ウィンドシアー監視用の空港気象ドップラーレーダーが設置されている

【図解】ドップラーレーダーが見る風
レーダー ))))) ▶ 雨粒が遠ざかる → 周波数下がる
レーダー ))))) ◀ 雨粒が近づく → 周波数上がる
×ただし測れるのは「視線方向」の成分だけ
　真横に動く粒の速度はゼロに見える
→ 弱点は複数レーダーの組み合わせや解析で補う

━━━━━━━━━━━━━━━━━━━━━━
🔑 二重偏波レーダー
━━━━━━━━━━━━━━━━━━━━━━
・水平偏波と垂直偏波の2種類の電波を同時に発射
・大きな雨粒は落下中に空気抵抗で「まんじゅう型（横長）」につぶれる
　→ 水平偏波のエコーが垂直より強くなる（ZDRが正）
・ひょうはほぼ球形または転がりながら落ちる → ZDRはほぼ0
→ 雨・雪・ひょうの判別、降水量推定の精度向上に貢献

【図解】粒の形と偏波の反応
大きな雨粒：⬭（横長）→ 水平＞垂直 → ZDR プラス
小さな雨粒：○（ほぼ球）→ 水平≒垂直 → ZDR ほぼ0
ひょう：●（球・回転）→ ZDR ほぼ0なのにエコー強い
→ 「エコー強×ZDR小」＝ひょうの疑い、と読み解く

⚠ ひっかけ注意
・レーダーが直接測るのはエコー強度と動径速度。「降水量そのもの」は推定値
・ドップラーレーダーで測れるのは視線方向の速度成分のみ（全風向風速ではない）
・Zは直径の6乗に比例（2乗や3乗ではない）
・山岳の陰（ビーム遮蔽）や地形エコーなど、レーダーには死角・偽エコーがある

★ここだけ暗記
★Z（反射因子）∝ 粒径の6乗。Z-R関係で降水強度へ換算
★ドップラー＝周波数偏移から視線方向の風（動径速度）
★二重偏波＝粒の形を判別（雨は横長ZDR正、ひょうはZDR≒0）
★解析雨量＝レーダー推定を雨量計で補正した約1kmメッシュの雨量分布`,
