        body: `▼ゼロから
地上や海上には観測点のない広い海洋域も、実は衛星から間接的に「温度」や「湿り」を測ることができます。可視・赤外画像だけでなく、目に見えないマイクロ波や電波の性質を利用した観測が、数値予報の初期値づくりを陰で支えています。

━━━━━━━━━━━━━━━━━━━━━━
🔑 マイクロ波サウンダによる鉛直プロファイル観測
━━━━━━━━━━━━━━━━━━━━━━
・気体分子（酸素分子や水蒸気分子）は特定のマイクロ波の波長を吸収・放射する性質がある
・その放射強度を衛星の複数のチャンネル（波長帯）で観測すると、大気の高度ごとの気温や水蒸気量を推定できる
・マイクロ波は雲を透過しやすいため、雲が多い海域でも大気の状態を観測しやすいという利点がある
・可視・赤外画像が「雲の様子」を見るのに対し、マイクロ波サウンダは「雲の下・雲の中を含めた大気の鉛直構造」を見るイメージ

【図解】観測手段による「見える深さ」の違い
可視・赤外画像　：雲の表面（雲頂）の様子が中心
マイクロ波サウンダ：雲を透過して鉛直方向の気温・水蒸気プロファイルを推定
→ 「表面を見る目」と「中まで見通す目」の役割分担

━━━━━━━━━━━━━━━━━━━━━━
🔑 GNSS掩蔽観測（GPS掩蔽観測）
━━━━━━━━━━━━━━━━━━━━━━
・GNSS（衛星測位システム）の電波が、地球の大気（特に電離層や対流圏）を通過する際にわずかに屈折する性質を利用する観測手法
・低軌道の観測衛星がGNSS衛星からの電波を、地球の縁をかすめるように受信し、電波が屈折した度合いから気温・気圧・水蒸気量の鉛直分布を高い精度で求める
・観測に特別な較正が要らず、長期にわたって精度が安定しているという利点があり、気候監視や数値予報の初期値づくりに活用される

【図解】GNSS掩蔽観測のしくみ
GNSS衛星 ──電波──▶ 大気の縁をかすめて屈折 ──▶ 低軌道の観測衛星が受信
　電波の屈折の度合い（伝わる速さ・角度の変化）から
　→ その経路上の気温・水蒸気の鉛直分布を逆算
→ 「電波が大気で曲がる量」を測って大気の状態を知る、間接的だが精密な観測

━━━━━━━━━━━━━━━━━━━━━━
🔑 衛星データ同化が数値予報にもたらす効果
━━━━━━━━━━━━━━━━━━━━━━
・海洋上や南半球など、地上観測やラジオゾンデの数が少ない地域の観測データを大きく補う
・観測地点が疎らな地域ほど、数値予報の初期値の質は衛星データに依存する割合が大きくなる
・データ同化（4次元変分法など）の枠組みの中で、衛星から得られる放射量・屈折角そのものを直接同化する手法（観測演算子を介した直接同化）も広く使われている

【図解】観測網の疎密と衛星データの重要性
陸上・先進国　　　：地上観測・ラジオゾンデが密　→ 衛星の役割は補完的
海洋・南半球など　：地上観測がまばら　　　　　　→ 衛星データが初期値の質を大きく左右
→ 「観測が少ない場所ほど、衛星が主役になる」という構図

⚠ ひっかけ注意
・マイクロ波サウンダは「雲を透過しやすい」のが利点。可視・赤外画像の代わりに雲の様子を見る道具ではない
・GNSS掩蔽観測は温度計や湿度計そのものを飛ばしているわけではなく、電波の屈折という間接的な物理量から気温・水蒸気を求める
・衛星データは地上観測を「完全に置き換える」ものではなく、観測が少ない地域を補う役割が大きい
・データ同化では、衛星から得た物理量（放射輝度や屈折角）をそのまま気温などに変換せず、観測演算子を介してモデルの変数と比較しながら取り込む手法が使われる

★ここだけ暗記
★マイクロ波サウンダ＝雲を透過する性質を利用し、気温・水蒸気の鉛直プロファイルを衛星から推定
★GNSS掩蔽観測＝GNSS電波が大気で屈折する度合いから気温・気圧・水蒸気の鉛直分布を求める観測
★衛星データは地上観測が少ない海洋・南半球などで特に重要
★衛星の観測量は観測演算子を介してデータ同化に直接取り込まれることが多い`,
