        body: `▼ゼロから
毎日空を飛び交う旅客機は、実は「動く気象観測装置」でもあります。定期便が飛行中に自動で送る気温・風のデータは、地上観測やゾンデ観測ではカバーしきれない上空のすき間を埋める、貴重な情報源になっています。空からの観測データがどのように使われているかを見ていきましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 AMDAR：航空機による自動気象観測
━━━━━━━━━━━━━━━━━━━━━━
・AMDAR（航空機によるデータ中継システム）は、旅客機などに搭載された機器が、飛行中の気温・風向風速などを自動的に観測し、地上へ無線で送信するしくみ
・特に離着陸の前後（上昇・下降中）には、地上から上空にかけての気温・風の鉛直分布に近いデータが得られるという利点がある
・世界中を飛び交う多数の定期便から得られるデータは、ラジオゾンデ観測（1日2回、決まった地点のみ、既習）を補う、時間的・空間的に密なデータ源として、数値予報のデータ同化（既習）に活用されている

【図解】ラジオゾンデとAMDARの補完関係
ラジオゾンデ：決まった地点で1日2回（00・12UTC）、高高度まで詳しい鉛直分布
AMDAR　　　：多数の航空路・空港周辺で高頻度、上昇・下降時に鉛直分布に近いデータ
→ 「決まった時刻・地点の精密な観測」と「多数・高頻度だが機体依存の観測」が互いに補い合う

━━━━━━━━━━━━━━━━━━━━━━
🔑 ライダー（レーザーを使った観測）
━━━━━━━━━━━━━━━━━━━━━━
・ライダーは、レーザー光を大気中に発射し、大気中の微小な粒子（エーロゾルなど）や分子による散乱光を受信することで、大気の状態を観測する技術
・電波を使う気象レーダーが主に雨や雪の粒（比較的大きな粒子）を捉えるのに対し、ライダーはより小さな粒子（エーロゾル、雲粒の一部など）を捉えることができ、降水のない晴天域の大気の様子（風の分布、エーロゾルの分布など）の観測にも用いられる
・ドップラー効果を利用したライダー（ドップラーライダー）では、風の分布を観測することもできる

【図解】レーダーとライダーの捉える対象の違い
気象レーダー（電波）：主に雨・雪などの比較的大きな降水粒子
ライダー（レーザー光）：エーロゾルや雲粒など、より小さな粒子（降水のない晴天域でも観測可能）
→ 「大きな粒を電波で」「小さな粒を光で」捉える、補完的な観測技術

━━━━━━━━━━━━━━━━━━━━━━
🔑 多様な観測手段を組み合わせる意義
━━━━━━━━━━━━━━━━━━━━━━
・地上観測・高層観測（ラジオゾンデ）・ウィンドプロファイラ・衛星観測・航空機観測（AMDAR）・レーダー・ライダーなど、既習の多様な観測手段は、それぞれ得意とする時間・空間スケールや対象が異なる
・これらを組み合わせることで、データ同化（既習）に使える観測情報の質と量が向上し、数値予報の初期値の精度向上につながる
・特に観測が少ない海洋上や上空では、衛星観測（既習）や航空機観測（AMDAR）のような、面的・高頻度にデータを取得できる手段の重要性が高い

⚠ ひっかけ注意
・AMDARは「地上の航空管制データ」ではなく、機体に搭載された気象観測機器による気温・風のデータである
・AMDARのデータは、定期便の運航経路・時刻に依存するため、ラジオゾンデのように「決まった地点・決まった時刻」で均等に得られるわけではない
・ライダーは電波ではなくレーザー光を用いる観測技術であり、気象レーダー（電波を用いる）とは原理が異なる
・ライダーは降水のない晴天域でも大気の状態（エーロゾル分布・風など）を観測できる点が、降水粒子を主に捉えるレーダーとの違い

★ここだけ暗記
★AMDAR＝航空機による自動気象観測。ラジオゾンデを補う高頻度・広域なデータ源
★ライダー＝レーザー光を用いた観測技術。エーロゾルなど小さな粒子や風の分布を観測できる
★レーダー（電波・降水粒子）とライダー（レーザー光・小さな粒子）は補完的な関係
★多様な観測手段の組み合わせが、データ同化・数値予報の精度向上を支える`,
