・逆転層の「上」に排出された汚染物質は逆転層を突き抜けにくいが、「下」の層では横方向にも拡散しにくいため蓄積する
・パスキル安定度階級は日射・風速などの条件から安定度を「区分」する考え方であり、絶対的な物理量そのものを直接測るものではない
