・逆転層の中にたまっていた水蒸気やちり、汚染物質は、逆転層が解消されるにつれて、上空のより広い体積に拡散されるため、地表付近の濃度は薄まっていく傾向がある
・そのため、朝の早い時間帯（逆転層がまだ残っている時間帯）は、地表付近の汚染物質濃度が比較的高くなりやすく、逆転層が解消される午前中にかけて薄まっていくという、1日の中でのパターンが見られることがある

