・メソ低気圧は総観規模の温帯低気圧とはスケール・成因が異なる、対流に伴う小さな渦である
・層状域の弱い雨も油断できない。長時間続けば総雨量は大きくなりうる
・メソ対流系は熱帯だけでなく中緯度（日本付近を含む）でも発生する現象である

