        body: `▼ゼロから
台風や温帯低気圧のような「本格的な低気圧」だけが低気圧ではありません。夏、強い日射で内陸の地表が猛烈に加熱されると、そこだけ気圧がわずかに下がる小さな低気圧が現れることがあります。これがサーマルロー（熱的低気圧）です。海陸風・山谷風といった局地循環が、より大きな低気圧とどう絡み合うかも見ていきましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 サーマルロー（熱的低気圧）とは
━━━━━━━━━━━━━━━━━━━━━━
・強い日射によって内陸の地表付近の空気が加熱されて膨張し、局地的に気圧がまわりよりわずかに低くなることで生じる、浅く小規模な低気圧
・前線や上空のトラフに伴う総観規模の低気圧とは異なり、主に地表付近だけの浅い現象で、日没後の放射冷却とともに弱まりやすい
・盆地や内陸の平野など、周囲より強く加熱されやすい地形でできやすいとされる

【図解】サーマルローができる仕組み（日中）
強い日射 → 内陸の地表が周囲より強く加熱
　↓
地表付近の空気が膨張・上昇 → 地表の気圧がわずかに低下
　↓
まわりから地表付近の風がその低圧部へ吹き込む（局地的な収束）
→ 総観規模の低気圧よりずっと小さく浅いが、しくみは「暖まった空気は軽く浮く」という既習の原理と同じ

━━━━━━━━━━━━━━━━━━━━━━
🔑 サーマルローと海風・山谷風の重なり
━━━━━━━━━━━━━━━━━━━━━━
・サーマルローができると、周辺の海岸から内陸へ向かう海風や、谷から山頂へ向かう谷風が、通常よりも強く・遠くまで吹き込みやすくなることがある
・複数方向からの海風・谷風がサーマルローに向かって収束すると、その収束線上で積乱雲が発達しやすくなり、内陸部での午後の雷雨の一因になることがある
・日没後、日射がなくなるとサーマルローは急速に弱まり、それに伴って強まっていた海風・谷風も弱まる

【図解】サーマルローに海風・谷風が収束するイメージ
　　海風→　　サーマルロー　　←海風
　　　　　　（内陸の低圧部）
　　　　　谷風↑　　　↑谷風
→ 複数方向の局地循環が1点（内陸の低圧部）へ集まる → 収束線上で対流が発達しやすい
→ 内陸で夕立・雷雨が発生しやすい理由のひとつとして説明されることがある

━━━━━━━━━━━━━━━━━━━━━━
🔑 実技での着眼点
━━━━━━━━━━━━━━━━━━━━━━
・地上天気図では総観規模の等圧線としては表現しきれないほど小さい現象であるため、地上天気図の等圧線だけからサーマルローを直接読み取ることは難しい
・むしろアメダスの気温分布（内陸で顕著に高温）や風向のデータ（複数方向からの海風・谷風の収束）から、サーマルローの存在を間接的に推定することが実技的なアプローチになる
・内陸で午後に発雷しやすい地域の天気を説明する際、総観規模が安定していても「サーマルローに伴う局地循環の収束」が対流のきっかけとして働きうる点を記述に加えられると評価されやすい

⚠ ひっかけ注意
・サーマルローは総観規模の温帯低気圧とはスケール・成因がまったく異なる、地表付近だけの浅い現象
・サーマルローが「発達した低気圧」に成長して台風や温帯低気圧になるわけではない（別種の現象）
・サーマルローは日射に依存するため、夜間には急速に弱まる。1日中同じ強さで存在し続けるわけではない
・地上天気図の等圧線だけを見て「低気圧がない」と判断しても、局地的なサーマルローが存在し対流の一因になっていることがある

★ここだけ暗記
★サーマルロー＝強い日射による内陸の加熱で生じる浅く小規模な熱的低気圧
★総観規模の低気圧とは別物。日没後は放射冷却で急速に弱まる
★サーマルローに向かって複数方向の海風・谷風が収束すると、内陸の午後の雷雨の一因になりうる
★実技ではアメダスの気温分布・風向データから間接的にサーマルローの存在を読み取る`,
