・顕熱フラックス：海面と大気の温度差によって伝わる熱のやり取り（既習の顕熱）
・潜熱フラックス：海面からの蒸発によって大気へ渡される熱のやり取り（既習の潜熱。海面から水蒸気とともに熱が持ち出される）
・運動量フラックス：風が海面を吹くことで海水にも運動が伝わり、海流や波を起こす（海面の摩擦を介したやり取り）
