・海洋の熱容量が大きいことは「海は変化しない」という意味ではなく、あくまで「変化がゆっくり」という意味
・台風のエネルギー源は海面水温そのものというより、暖かい海面から供給される水蒸気が凝結するときの潜熱である
・台風が通過すると海面水温が下がる効果があり、これが台風自身の発達を抑える方向に働くことがある

