        emoji: '🌊',
        body: `▼ゼロから
海の波は、その場で吹いている風だけが作っているとは限りません。遠く離れた台風が作った波が、何百kmも旅をして静かな晴れの日の海岸に打ち寄せることがあります。波にも「今作られたばかりの波」と「遠くからやってきた波」の2種類があることを知ると、海の状況を読み解く力がぐっと上がります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 風浪とうねりの違い
━━━━━━━━━━━━━━━━━━━━━━
・風浪：その場で吹いている風によって、直接起こされている波。風が強いほど、また吹き続ける時間・距離（吹走時間・吹走距離）が長いほど、波は高く発達する
・うねり：発生した場所から離れ、風による直接の影響を受けなくなった後も、水面の波として周期の長い、なめらかな形を保ちながら遠くまで伝わっていく波
・風浪は波形が不規則で波長が短めなのに対し、うねりは波形が規則的で波長が長く、周期がそろっているという特徴がある

【図解】風浪からうねりへの変化
台風などの強風域　→　その場で風浪が発生（不規則・波長短め）
　↓ 強風域から離れる（または台風が遠ざかる・弱まる）
風の直接の影響を受けなくなった波　→　うねりとして規則的な形で遠方まで伝わる
→ 「生まれたての波（風浪）」が「旅をする波（うねり）」に姿を変えるイメージ

━━━━━━━━━━━━━━━━━━━━━━
🔑 有義波高という考え方
━━━━━━━━━━━━━━━━━━━━━━
・有義波高：観測された波の中から、波高の高い方から順に選んだおよそ上位3分の1の波の平均的な高さとして定義される、波の高さの代表的な指標
・体感的・統計的に「今の海はこれくらいの高さの波が代表的」という目安として、波浪の実況・予報で広く用いられる
・有義波高は、あくまで代表的な高さの目安であり、実際にはこれより高い個々の波（発達した風浪では、ときに有義波高の1.5倍程度に達するような高い波）が混じって出現することがある

【図解】有義波高のイメージ
観測された多数の波の高さを、高い順に並べる
上位およそ1/3の波を取り出し、その平均的な高さ　＝　有義波高
→ 「一番高い波」でも「単純な全波の平均」でもなく、上位グループの平均という点がポイント

━━━━━━━━━━━━━━━━━━━━━━
🔑 波浪と台風・低気圧との関連
━━━━━━━━━━━━━━━━━━━━━━
・台風や発達した低気圧の強風域では、風速が強いほど、また吹走距離・吹走時間が長いほど、有義波高は高くなる傾向がある
・台風の進行方向前面（進行方向側）では、うねりが台風本体より先に到達し、青空の下でも「うねりによるところどころ高い波」が押し寄せることがある（台風接近の前触れとして注意喚起される現象）
・台風が海上を通過した後も、発達した風浪やうねりが海域に残り、しばらく高波が続くことがある

⚠ ひっかけ注意
・「うねり」は風がやんでもすぐには収まらない。風が弱まった後もしばらく高い波が残ることがある
・有義波高は「波の最大の高さ」ではなく、上位およそ1/3の波の平均的な高さという定義であることに注意
・晴れて風が弱い日でも、遠方の台風のうねりによって突然高い波が来ることがある（「凪いでいるから安全」とは限らない）
・風浪は波形が不規則、うねりは波形が規則的という違いも、実況を見分ける手がかりになる

★ここだけ暗記
★風浪＝その場の風で直接発生する不規則な波、うねり＝発生源を離れて規則的に遠方まで伝わる波
★有義波高＝観測された波のうち、高い方から上位およそ1/3の平均的な高さ
★波高は風速・吹走距離・吹走時間が大きいほど高くなる
★台風のうねりは本体より先に到達することがあり、晴天でも高波に注意が必要`,
