★ここだけ暗記
★再現期間＝ある強さ以上の現象が平均的に何年に1回程度発生するかを表す統計的指標（極値統計から算出）
★「100年に1回」は決定論的な周期ではなく、統計的な発生確率の見積もり
★短期間に連続して「稀な現象」が発生することも統計的にありうる
