        body: `▼ゼロから
「昔より夏が暑くなった気がする」という体感は、実は観測データにも表れています。ここでは、これまで学んできた温暖化・異常気象の理屈を、日本で実際に観測されているとされる長期的な傾向というかたちで確認します。個々の年の天候ではなく、長期的な「傾向」として捉える視点を養いましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 気温に関する長期的な観測傾向
━━━━━━━━━━━━━━━━━━━━━━
・日本の平均気温は、長期的に見て上昇傾向にあることが、気象庁などの長期間の観測データの統計から示されているとされる
・猛暑日（1日の最高気温が35℃以上の日）や熱帯夜（夜間の最低気温が25℃以上の日）とされる日数は、長期的には増加傾向にあるとされる
・一方、冬日（1日の最低気温が0℃未満の日）とされる日数は、長期的には減少傾向にあるとされる
→ 「暑い方の極端」が増え、「寒い方の極端」が減る、という非対称な変化が指摘されている

【図解】長期的な気温の極端指標の傾向（模式的なイメージ）
猛暑日・熱帯夜の日数　：長期的に増加傾向
冬日の日数　　　　　　：長期的に減少傾向
→ 「両方増えている」わけではなく、暑い側の極端が増え、寒い側の極端が減る非対称な変化

━━━━━━━━━━━━━━━━━━━━━━
🔑 降水に関する長期的な観測傾向
━━━━━━━━━━━━━━━━━━━━━━
・1時間に降る雨の量が非常に多い「短時間強雨」の発生回数は、長期的には増加傾向にあるとされる
・一方で、大雨や短時間強雨の増加傾向がある一方、年間の降水日数（雨が降った日の合計日数）自体は長期的に減少傾向にあるとされることがある
・つまり「雨が降る日は減っているが、降るときは激しく降る」という、降り方が極端化する傾向が指摘されている

【図解】降水の長期的な傾向（模式的なイメージ）
短時間強雨（1時間に多量の雨）の発生回数　：長期的に増加傾向
年間の降水日数　　　　　　　　　　　　　：長期的に減少傾向
→ 「メリハリが強くなる」方向の変化として整理できる

━━━━━━━━━━━━━━━━━━━━━━
🔑 傾向を語る際の実技的な注意点
━━━━━━━━━━━━━━━━━━━━━━
・長期的な傾向は、あくまで数十年スケールの統計から導かれるものであり、特定の1年・1つの現象を「傾向どおりだ」と単純に評価するのは適切ではない
・年ごとの変動（エルニーニョ・ラニーニャなどの自然変動）は、長期的な傾向に対して大きな振れ幅を与えるため、1年だけの記録的な現象を見て「これが気候変動そのものだ」と断定することは避けるべきである
・記述式の解答では「長期的な統計としては〇〇の傾向が指摘されているが、個々の年の現象には自然変動の影響も大きい」という両論併記的な書き方が、科学的に誠実な説明として評価されやすい

⚠ ひっかけ注意
・「猛暑日が増えている」からといって、毎年必ず猛暑日が前年より増えるという意味ではない（あくまで長期的な統計としての傾向）
・降水日数が減少傾向にあることと、短時間強雨の発生回数が増加傾向にあることは矛盾しない（「降る日は減るが、降るときは激しい」という関係）
・個々の記録的な現象（観測史上一位の高温・大雨など）を、単独で温暖化の証拠として断定するのは科学的に不正確
・長期的な傾向の話と、数年周期の自然変動（エルニーニョなど）の話は、異なる時間スケールの議論として区別する

★ここだけ暗記
★猛暑日・熱帯夜は長期的に増加傾向、冬日は長期的に減少傾向とされる
★短時間強雨の発生回数は長期的に増加傾向、一方で年間降水日数は減少傾向とされる
★降水の傾向は「メリハリが強くなる（少雨と強雨の両極化）」方向として整理できる
★長期的な傾向と、個々の年の自然変動（エルニーニョ等）は分けて説明することが実技上も重要`,
